head.script:

// 사용자 ID 생성 함수
const generateUserId = () => {
    const timestamp = Date.now();
    const random = Math.floor(Math.random() * 1000);
    return `mobile_${timestamp}_${random}`;
};

// WebRTC 관련 변수들
let peerConnections = new Map();
let localStream = null;
let chatSocket = null;
let isJoined = false;
let projectId = 'default';

// 사용자 정보 
let currentUser = {
    userId: generateUserId(),
    userName: "모바일사용자",
    channelName: ""
};

// ICE 서버 설정
const iceServers = {
    iceServers: [
        { urls: 'stun:stun.l.google.com:19302' },
        { urls: 'stun:stun1.l.google.com:19302' },
        {
            urls: 'turn:openrelay.metered.ca:80',
            username: 'openrelayproject',
            credential: 'openrelayproject'
        }
    ]
};

scwin.onpageload = function() {
    console.log("하이브리드 화상통화 연결 페이지 로드");

    // 팝업 파라미터에서 프로젝트 ID 받기 (여러 방법 시도)
    try {
        // 1차 시도: paramObject에서 직접 받기
        var paramObj = $p.getParameter("paramObject");
        if (paramObj && paramObj.projectId) {
            projectId = paramObj.projectId;
            console.log("paramObject에서 프로젝트 ID 획득:", projectId);
        } else {
            // 2차 시도: 기본 getParameter 방식
            projectId = $p.getParameter("projectId");
            console.log("기본 방식으로 프로젝트 ID 획득:", projectId);
        }

        // 3차 시도: 모든 파라미터 확인
        if (!projectId) {
            console.log("모든 파라미터 확인:", $p.getParameter());

            // 4차 시도: 부모 창에서 프로젝트 ID 가져오기
            try {
                var parentWindow = $p.parent();
                if (parentWindow && parentWindow.scwin && parentWindow.scwin.currentProjectData) {
                    projectId = parentWindow.scwin.currentProjectData.projectId;
                    console.log("부모 창에서 프로젝트 ID 획득:", projectId);
                }
            } catch (parentError) {
                console.log("부모 창 접근 실패:", parentError);
            }
        }

        // 최종 체크
        if (!projectId) {
            console.error("모든 방법으로 프로젝트 ID를 찾을 수 없습니다!");
            projectId = 'default';
        } else {
            console.log("최종 확정된 프로젝트 ID:", projectId);
        }

    } catch (e) {
        console.error("프로젝트 ID 추출 중 오류 발생:", e);
        projectId = 'default';
    }

    // 채널명을 데스크톱과 동일한 형식으로 설정
    currentUser.channelName = "webrtc-room-" + projectId;

    console.log("생성된 채널명:", currentUser.channelName);

    // 사용자 정보 설정
    dma_videoChat.set("userId", currentUser.userId);
    dma_videoChat.set("userName", currentUser.userName);
    dma_videoChat.set("channelName", currentUser.channelName);
    dma_videoChat.set("isJoined", "false");
    dma_videoChat.set("isMuted", "false");
    dma_videoChat.set("isVideoOff", "false");

    // 사용자 정보 로드
    $p.executeSubmission("sbm_getUserInfo");

    // 하이브리드 화상통화 시작
    scwin.startHybridVideoCall();
};

// 사용자 정보 로드 완료
scwin.sbm_getUserInfo_submitdone = function(e) {
    try {
        console.log("세션 사용자 정보 로드 완료:", e);

        var sessionUserId = dm_userInfo.get("userId");
        var sessionUserName = dm_userInfo.get("userName");

        // 실제 로그인 사용자 정보로 업데이트
        if (sessionUserId && sessionUserName) {
            currentUser.userId = sessionUserId;
            currentUser.userName = sessionUserName;

            // 데이터 바인딩 업데이트
            dma_videoChat.set("userId", currentUser.userId);
            dma_videoChat.set("userName", currentUser.userName);
        }

        console.log("사용자 정보 업데이트:", currentUser);

    } catch (error) {
        console.error("사용자 정보 처리 실패:", error);
    }
};

scwin.sbm_getUserInfo_submiterror = function(e) {
    console.error("사용자 정보 로드 실패:", e);
};

// WebSocket 초기화
scwin.initializeWebSocket = function() {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const host = window.location.hostname;
    const port = window.location.port || (protocol === 'wss:' ? '443' : '80');

    const wsUrls = [
        `${protocol}//${host}:${port}/InsWebApp/chat`,
        `ws://localhost:9093/InsWebApp/chat`,
        `wss://localhost:19443/InsWebApp/chat`
    ];

    let wsUrl = wsUrls[0];

    try {
        chatSocket = new WebSocket(wsUrl);

        chatSocket.onopen = function() {
            console.log("WebSocket 연결 성공:", wsUrl);

            // 채널 참가
            const joinMessage = {
                type: 'join',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName
            };
            chatSocket.send(JSON.stringify(joinMessage));
        };

        chatSocket.onmessage = function(event) {
            const data = JSON.parse(event.data);
            scwin.handleWebSocketMessage(data);
        };

        chatSocket.onclose = function(event) {
            console.log("WebSocket 연결 종료:", event);
        };

        chatSocket.onerror = function(error) {
            console.error("WebSocket 오류:", error);
        };
    } catch (error) {
        console.error("WebSocket 초기화 실패:", error);
    }
};

// 직접 WebRTC 구현 테스트 - Matrix Mobile에서 실제로 어디까지 가능한지 확인
scwin.startHybridVideoCall = function() {
    try {
        console.log("Matrix Mobile WebRTC 직접 구현 테스트 시작");
        alert("Matrix Mobile WebRTC 직접 구현 테스트를 시작합니다");

        // 실제 WebRTC 구현 단계별 테스트
        scwin.testDirectWebRTCImplementation();

    } catch (error) {
        console.error("WebRTC 직접 구현 테스트 실패:", error);
        alert("테스트 실패: " + error.message);
    }
};

// Matrix Mobile WebRTC 직접 구현 단계별 테스트
scwin.testDirectWebRTCImplementation = async function() {
    try {
        alert("1단계: WebRTC 환경 체크 시작");

        // 1단계: 기본 환경 체크
        alert("1-1. 프로토콜 체크: " + location.protocol);
        alert("1-2. 호스트: " + location.hostname);
        alert("1-3. navigator 존재: " + (typeof navigator !== 'undefined'));
        alert("1-4. navigator.mediaDevices 존재: " + (typeof navigator.mediaDevices !== 'undefined'));
        alert("1-5. getUserMedia 함수 존재: " + (navigator.mediaDevices && typeof navigator.mediaDevices.getUserMedia === 'function'));
        alert("1-6. RTCPeerConnection 존재: " + (typeof RTCPeerConnection !== 'undefined'));

        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            alert("❌ getUserMedia를 사용할 수 없습니다");
            return;
        }

        alert("2단계: 카메라 권한 요청 시작");
        scwin.showLoading("카메라 권한 요청 중...");

        // 2단계: 카메라 권한 요청
        alert("2-1. getUserMedia() 호출 시작");

        const stream = await navigator.mediaDevices.getUserMedia({
            video: { 
                width: 640, 
                height: 480, 
                facingMode: "user" // 전면 카메라 
            },
            audio: false
        });

        alert("2-2. ✅ getUserMedia 성공! 스트림 획득됨");
        alert("2-3. 스트림 ID: " + stream.id);
        alert("2-4. 비디오 트랙 수: " + stream.getVideoTracks().length);
        alert("2-5. 오디오 트랙 수: " + stream.getAudioTracks().length);

        // 비디오 트랙 상세 정보
        const videoTrack = stream.getVideoTracks()[0];
        if (videoTrack) {
            alert("2-6. 비디오 트랙 라벨: " + videoTrack.label);
            alert("2-7. 비디오 트랙 상태: " + videoTrack.readyState);
            alert("2-8. 비디오 트랙 활성화: " + videoTrack.enabled);
        }

        // 3단계: 비디오 엘리먼트에 스트림 연결
        alert("3단계: video 엘리먼트에 스트림 연결 시작");
        await scwin.connectStreamToVideoElement(stream);

        // 4단계: RTCPeerConnection 테스트
        alert("4단계: RTCPeerConnection 생성 및 테스트");
        await scwin.testRTCPeerConnection(stream);

        // 5단계: 실제 화상통화 시뮬레이션
        alert("5단계: 실제 화상통화 시뮬레이션");
        scwin.simulateVideoCall(stream);

    } catch (error) {
        console.error("WebRTC 구현 실패:", error);
        alert("❌ 실패한 단계에서 에러 발생");
        alert("에러 이름: " + error.name);
        alert("에러 메시지: " + error.message);
        alert("에러 상세: " + JSON.stringify(error));
        scwin.hideLoading();
    }
};

// 3단계: 스트림을 video 엘리먼트에 연결
scwin.connectStreamToVideoElement = async function(stream) {
    try {
        alert("3-1. video 엘리먼트 생성 시작");

        // 비디오 그리드 찾기
        const grid = document.querySelector('.mobile-videos-grid');
        if (!grid) {
            alert("3-2. ❌ 비디오 그리드를 찾을 수 없습니다");
            return;
        }

        // 기존 비디오 제거
        grid.innerHTML = '';

        // 새 비디오 엘리먼트 생성
        alert("3-3. 새 video 엘리먼트 생성");
        const videoContainer = document.createElement('div');
        videoContainer.className = 'mobile-user-video';
        videoContainer.id = 'test-video-container';

        const videoWrapper = document.createElement('div');
        videoWrapper.className = 'mobile-video-wrapper';

        const video = document.createElement('video');
        video.id = 'test-video-element';
        video.autoplay = true;
        video.playsInline = true;
        video.muted = true;
        video.style.width = '100%';
        video.style.height = '100%';

        alert("3-4. video.srcObject에 스트림 연결 시도");
        video.srcObject = stream;

        const nameTag = document.createElement('div');
        nameTag.className = 'mobile-user-name';
        nameTag.textContent = currentUser.userName + " (테스트)";

        videoWrapper.appendChild(video);
        videoWrapper.appendChild(nameTag);
        videoContainer.appendChild(videoWrapper);
        grid.appendChild(videoContainer);

        alert("3-5. ✅ video 엘리먼트 DOM에 추가 완료");

        // 비디오 로드 대기
        return new Promise((resolve, reject) => {
            video.addEventListener('loadedmetadata', function() {
                alert("3-6. ✅ 비디오 메타데이터 로드 완료");
                alert("3-7. 비디오 크기: " + video.videoWidth + "x" + video.videoHeight);
                resolve();
            });

            video.addEventListener('play', function() {
                alert("3-8. ✅ 비디오 재생 시작!");
                alert("3-9. 실시간 카메라 영상이 화면에 표시되고 있나요?");
            });

            video.addEventListener('error', function(e) {
                alert("3-6. ❌ 비디오 로드 에러: " + e.message);
                reject(e);
            });

            // 5초 후 타임아웃
            setTimeout(() => {
                if (video.readyState === 0) {
                    alert("3-6. ⚠️ 비디오 로드 타임아웃 (5초)");
                    resolve(); // 에러가 아닌 타임아웃으로 처리
                }
            }, 5000);
        });

    } catch (error) {
        alert("3단계 실패: " + error.message);
        throw error;
    }
};

// 4단계: RTCPeerConnection 테스트
scwin.testRTCPeerConnection = async function(stream) {
    try {
        alert("4-1. RTCPeerConnection 생성 시도");

        const pcConfig = {
            iceServers: [
                { urls: 'stun:stun.l.google.com:19302' },
                { urls: 'stun:stun1.l.google.com:19302' }
            ]
        };

        const pc = new RTCPeerConnection(pcConfig);
        alert("4-2. ✅ RTCPeerConnection 생성 성공");
        alert("4-3. 연결 상태: " + pc.connectionState);
        alert("4-4. ICE 연결 상태: " + pc.iceConnectionState);

        // 스트림 트랙을 PeerConnection에 추가
        alert("4-5. 스트림 트랙을 PeerConnection에 추가");
        let trackCount = 0;
        stream.getTracks().forEach(track => {
            pc.addTrack(track, stream);
            trackCount++;
            alert("4-6. " + track.kind + " 트랙 추가 (" + trackCount + "개)");
        });

        alert("4-7. ✅ 모든 트랙이 PeerConnection에 추가됨");

        // ICE 후보 수집 테스트
        let iceGatheringComplete = false;
        pc.onicecandidate = function(event) {
            if (event.candidate) {
                alert("4-8. ICE 후보 수집: " + event.candidate.type);
            } else {
                alert("4-9. ✅ ICE 후보 수집 완료");
                iceGatheringComplete = true;
            }
        };

        // 연결 상태 변화 모니터링
        pc.onconnectionstatechange = function() {
            alert("4-10. 연결 상태 변화: " + pc.connectionState);
        };

        // Offer 생성 테스트
        alert("4-11. SDP Offer 생성 시도");
        const offer = await pc.createOffer();
        await pc.setLocalDescription(offer);

        alert("4-12. ✅ SDP Offer 생성 성공");
        alert("4-13. Offer SDP 길이: " + offer.sdp.length + " 문자");

        alert("4-14. ✅ RTCPeerConnection 테스트 완료");
        alert("4-15. 실제 상대방이 있다면 화상통화 연결이 가능합니다!");

    } catch (error) {
        alert("4단계 실패: " + error.message);
        throw error;
    }
};

// 5단계: 실제 화상통화 시뮬레이션
scwin.simulateVideoCall = function(stream) {
    try {
        alert("5-1. 실제 화상통화 시뮬레이션 시작");

        // WebSocket 연결 상태 확인
        alert("5-2. WebSocket 연결 상태 확인");
        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            alert("5-3. ✅ WebSocket 연결됨 - 상대방 찾기 가능");
        } else {
            alert("5-3. ⚠️ WebSocket 연결 안됨 - 연결 시도");
            scwin.initializeWebSocket();
        }

        // 화상통화 방 참가
        alert("5-4. 화상통화 방 참가 시뮬레이션");
        const joinMessage = {
            type: 'join-room',
            channelName: currentUser.channelName,
            userId: currentUser.userId,
            userName: currentUser.userName,
            hasVideo: true,
            timestamp: Date.now()
        };

        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            chatSocket.send(JSON.stringify(joinMessage));
            alert("5-5. ✅ 화상통화 방 참가 메시지 전송 완료");
        }

        // 로컬 스트림 저장
        localStream = stream;

        // 화상통화 상태 업데이트
        isJoined = true;
        dma_videoChat.set("isJoined", "true");

        alert("5-6. ✅ 화상통화 시뮬레이션 완료!");
        alert("5-7. ������ Matrix Mobile에서 WebRTC 화상통화 구현 성공!");
        alert("5-8. 상대방이 접속하면 실시간 화상통화가 가능합니다");

        scwin.hideLoading();

        // 최종 성공 메시지
        setTimeout(function() {
            alert("������ 축하합니다! Matrix Mobile 팝업에서 실시간 화상통화가 성공적으로 구현되었습니다!");
        }, 1000);

    } catch (error) {
        alert("5단계 실패: " + error.message);
        throw error;
    }
};

