// 로딩 메시지 업데이트
scwin.updateLoadingMessage = function(message) {
    const loadingContent = document.querySelector('.loading-content');
    if (loadingContent && loadingContent.children.length > 0) {
        loadingContent.children[0].textContent = message;
    }
};

