// 에러 표시
scwin.showError = function(message) {
    scwin.hideLoading();
    alert("오류: " + message);

    // 에러 발생 시에도 팝업은 닫기
    setTimeout(function() {
        if (typeof $p !== 'undefined' && $p.closePopup) {
            $p.closePopup("videoPopup");
        }
    }, 2000);
};

// WebRTC 화상통화 올바른 구현 순서
scwin.requestCameraPermission = async function() {
    try {
        // 1단계: 기본 환경 체크
        alert("1단계: WebRTC 환경 체크 시작");
        alert("- HTTPS: " + (location.protocol === 'https:' ? '✅' : '❌'));
        alert("- getUserMedia: " + (navigator.mediaDevices && navigator.mediaDevices.getUserMedia ? '✅' : '❌'));
        alert("- RTCPeerConnection: " + (typeof RTCPeerConnection !== 'undefined' ? '✅' : '❌'));

        scwin.showLoading("1단계: 카메라/마이크 권한 요청 중...");

        // 1단계: navigator.mediaDevices.getUserMedia로 카메라/마이크 권한 요청
        alert("1단계 실행: getUserMedia() 호출");
        localStream = await navigator.mediaDevices.getUserMedia({
            video: { 
                width: 640, 
                height: 480,
                facingMode: "user" // 전면 카메라 우선
            },
            audio: false
        });

        alert("1단계 성공! ✅ 카메라/마이크 권한 획득 완료");
        alert("- 비디오 트랙: " + localStream.getVideoTracks().length + "개");
        alert("- 오디오 트랙: " + localStream.getAudioTracks().length + "개");

        // 스트림 상태 확인
        const videoTrack = localStream.getVideoTracks()[0];
        if (videoTrack) {
            alert("- 비디오 트랙 상태: " + videoTrack.readyState);
            alert("- 카메라 활성화: " + videoTrack.enabled);
            alert("- 카메라 라벨: " + videoTrack.label);
        }

        scwin.hideLoading();

        // 2단계로 진행
        scwin.connectStreamToVideo();

    } catch (error) {
        console.error("1단계 실패:", error);
        alert("1단계 실패! ❌ " + error.name + ": " + error.message);

        // 에러 타입에 따른 상세 안내
        if (error.name === 'NotAllowedError') {
            alert("권한 거부: 브라우저 설정에서 카메라/마이크 권한을 허용해주세요");
        } else if (error.name === 'NotFoundError') {
            alert("장치 없음: 카메라나 마이크가 연결되어 있지 않습니다");
        } else if (error.name === 'NotSupportedError') {
            alert("지원 안함: 이 브라우저에서는 WebRTC를 지원하지 않습니다");
        }

        scwin.hideLoading();
    }
};

// 2단계: MediaStream을 video 엘리먼트에 연결
scwin.connectStreamToVideo = function() {
    try {
        alert("2단계 시작: MediaStream을 video 엘리먼트에 연결");

        if (!localStream) {
            alert("2단계 실패: localStream이 없습니다");
            return;
        }

        // video 엘리먼트 생성
        const grid = document.querySelector('.mobile-videos-grid');
        if (!grid) {
            alert("2단계 실패: 비디오 그리드를 찾을 수 없습니다");
            return;
        }

        // 기존 로컬 비디오 제거
        const existing = document.getElementById('local-video-' + currentUser.userId);
        if (existing) {
            existing.remove();
        }

        // 새 비디오 엘리먼트 생성
        const videoDiv = document.createElement('div');
        videoDiv.className = 'mobile-user-video';
        videoDiv.id = 'local-video-' + currentUser.userId;

        const wrapper = document.createElement('div');
        wrapper.className = 'mobile-video-wrapper';

        const video = document.createElement('video');

        // 2단계 핵심: MediaStream을 video.srcObject에 연결
        alert("2단계 핵심 실행: video.srcObject = localStream");
        video.srcObject = localStream;
        video.autoplay = true;
        video.muted = true; // 로컬 비디오는 음소거
        video.playsInline = true;

        const nameTag = document.createElement('div');
        nameTag.className = 'mobile-user-name';
        nameTag.textContent = currentUser.userName + " (나)";

        wrapper.appendChild(video);
        wrapper.appendChild(nameTag);
        videoDiv.appendChild(wrapper);
        grid.appendChild(videoDiv);

        alert("2단계 성공! ✅ video 엘리먼트에 스트림 연결 완료");
        alert("- video.srcObject 설정 완료");
        alert("- autoplay: " + video.autoplay);
        alert("- muted: " + video.muted);

        // 3단계로 진행
        scwin.displayRealTimeVideo();

    } catch (error) {
        console.error("2단계 실패:", error);
        alert("2단계 실패! ❌ " + error.message);
    }
};

// 3단계: 화면에 실시간 카메라 영상 표시
scwin.displayRealTimeVideo = function() {
    try {
        alert("3단계 시작: 실시간 카메라 영상 화면 표시 확인");

        const video = document.querySelector('#local-video-' + currentUser.userId + ' video');
        if (!video) {
            alert("3단계 실패: 비디오 엘리먼트를 찾을 수 없습니다");
            return;
        }

        // 비디오 재생 상태 확인
        alert("3단계 확인중: 비디오 재생 상태");
        alert("- video.srcObject 존재: " + (video.srcObject ? '✅' : '❌'));
        alert("- video.videoWidth: " + video.videoWidth);
        alert("- video.videoHeight: " + video.videoHeight);
        alert("- video.readyState: " + video.readyState);

        // 비디오 메타데이터 로드 이벤트 리스너
        video.addEventListener('loadedmetadata', function() {
            alert("3단계 이벤트: 비디오 메타데이터 로드 완료");
            alert("- 실제 비디오 크기: " + video.videoWidth + "x" + video.videoHeight);
        });

        // 비디오 재생 시작 이벤트 리스너
        video.addEventListener('play', function() {
            alert("3단계 성공! ✅ 실시간 카메라 영상 재생 시작");
            alert("화면에 내 얼굴이 보이나요?");

            // 4단계로 진행
            setTimeout(function() {
                scwin.setupRTCPeerConnection();
            }, 2000);
        });

        // 비디오 에러 이벤트 리스너
        video.addEventListener('error', function(e) {
            alert("3단계 실패: 비디오 재생 에러 - " + e.message);
        });

        // 강제로 재생 시도
        if (video.paused) {
            video.play().then(function() {
                alert("3단계: 비디오 재생 시작 명령 성공");
            }).catch(function(error) {
                alert("3단계 실패: 비디오 재생 실패 - " + error.message);
            });
        }

    } catch (error) {
        console.error("3단계 실패:", error);
        alert("3단계 실패! ❌ " + error.message);
    }
};

// 4단계: RTCPeerConnection으로 상대방과 연결
scwin.setupRTCPeerConnection = function() {
    try {
        alert("4단계 시작: RTCPeerConnection 설정");

        if (!localStream) {
            alert("4단계 실패: localStream이 없습니다");
            return;
        }

        // RTCPeerConnection 생성
        alert("4단계-1: RTCPeerConnection 생성");
        const testPC = new RTCPeerConnection({
            iceServers: [
                { urls: 'stun:stun.l.google.com:19302' },
                { urls: 'stun:stun1.l.google.com:19302' }
            ]
        });

        alert("4단계-1 성공: RTCPeerConnection 생성 완료");
        alert("- 연결 상태: " + testPC.connectionState);
        alert("- ICE 연결 상태: " + testPC.iceConnectionState);

        // 4단계 핵심: MediaStream을 RTCPeerConnection에 추가
        alert("4단계-2: MediaStream을 PeerConnection에 추가");
        let trackCount = 0;
        localStream.getTracks().forEach(track => {
            testPC.addTrack(track, localStream);
            trackCount++;
            alert("- 트랙 추가: " + track.kind + " (" + trackCount + "개)");
        });

        alert("4단계-2 성공: 모든 트랙이 PeerConnection에 추가됨");

        // ICE 후보 수집 테스트
        testPC.onicecandidate = function(event) {
            if (event.candidate) {
                alert("4단계-3: ICE 후보 수집 완료 - " + event.candidate.type);
            }
        };

        // 연결 상태 변화 모니터링
        testPC.onconnectionstatechange = function() {
            alert("4단계 상태 변화: " + testPC.connectionState);
        };

        alert("4단계 성공! ✅ RTCPeerConnection 설정 완료");
        alert("이제 상대방과 실시간 화상통화 연결이 가능합니다!");

        // 실제 화상통화 초기화
        scwin.initializeVideoCall();

    } catch (error) {
        console.error("4단계 실패:", error);
        alert("4단계 실패! ❌ " + error.message);
    }
};

// 실제 화상통화 초기화 (기존 시스템과 연결)
