// 주기적 사진 전송 테스트
scwin.startPhotoStreamingMode = function() {
    alert("57. 주기적 사진 전송 테스트 시작");
    alert("58. 3초마다 사진 촬영 예정");

    var photoCount = 0;
    var maxPhotos = 3; // 테스트용으로 3장만

    var photoInterval = setInterval(function() {
        photoCount++;
        alert("59-" + photoCount + ". " + photoCount + "번째 사진 촬영 중...");

        $h.camera.capturePhoto(function(result) {
            if (result.statusCode === "SUCCESS") {
                alert("60-" + photoCount + ". 사진 촬영 성공!");
                // 실제로는 WebSocket으로 전송
                console.log("사진 데이터:", result.data);
            } else {
                alert("60-" + photoCount + ". 사진 촬영 실패: " + result.msg);
            }
        }, {
            "quality": 30, // 전송용으로 낮춤
            "sourceType": $h.camera.PictureSourceType.CAMERA,
            "allowEdit": false,
            "encodingType": $h.camera.EncodingType.JPEG,
            "destinationType": $h.camera.DestinationType.DATA_URL // Base64 데이터
        });

        if (photoCount >= maxPhotos) {
            clearInterval(photoInterval);
            alert("61. 주기적 사진 전송 테스트 완료!");
            alert("62. 준실시간 화상통화 구현 가능!");
        }
    }, 3000);
};

